#include <bits/stdc++.h>
using namespace std;

const int MAXG = 32;

struct Item {
    int g, cnt;
};

struct Node {
    long long ans;
    int g;
    int szPref, szSuff;
    Item pref[MAXG], suff[MAXG];

    Node() : ans(0), g(0), szPref(0), szSuff(0) {}
};

Node make_leaf(int x) {
    Node n;
    n.ans = (x > 1 ? 1LL : 0LL);
    n.g = x;
    n.pref[0] = {x, 1};
    n.suff[0] = {x, 1};
    n.szPref = n.szSuff = 1;
    return n;
}

Node combine(const Node& A, const Node& B) {
    if (A.szPref == 0) return B;
    if (B.szPref == 0) return A;

    Node C;
    C.ans = A.ans + B.ans;
    C.g = std::gcd(A.g, B.g);

    for (int i = 0; i < A.szSuff; ++i) {
        int ga = A.suff[i].g;
        int ca = A.suff[i].cnt;
        for (int j = 0; j < B.szPref; ++j) {
            if (std::gcd(ga, B.pref[j].g) > 1) {
                C.ans += 1LL * ca * B.pref[j].cnt;
            }
        }
    }

    int sz = 0;
    for (int i = 0; i < A.szPref; ++i) {
        C.pref[sz++] = A.pref[i];
    }
    for (int j = 0; j < B.szPref; ++j) {
        int val = std::gcd(A.g, B.pref[j].g);
        int cnt = B.pref[j].cnt;
        if (sz > 0 && C.pref[sz - 1].g == val) {
            C.pref[sz - 1].cnt += cnt;
        } else {
            C.pref[sz++] = {val, cnt};
        }
    }
    C.szPref = sz;

    sz = 0;
    for (int i = 0; i < B.szSuff; ++i) {
        C.suff[sz++] = B.suff[i];
    }
    for (int i = 0; i < A.szSuff; ++i) {
        int val = std::gcd(A.suff[i].g, B.g);
        int cnt = A.suff[i].cnt;
        if (sz > 0 && C.suff[sz - 1].g == val) {
            C.suff[sz - 1].cnt += cnt;
        } else {
            C.suff[sz++] = {val, cnt};
        }
    }
    C.szSuff = sz;

    return C;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<Node> seg(2 * N);

    for (int i = 0; i < N; ++i) {
        int x;
        cin >> x;
        seg[N + i] = make_leaf(x);
    }

    for (int i = N - 1; i >= 1; --i) {
        seg[i] = combine(seg[2 * i], seg[2 * i + 1]);
    }

    while (M--) {
        int T;
        cin >> T;

        if (T == 1) {
            int I, V;
            cin >> I >> V;
            --I;

            int p = N + I;
            seg[p] = make_leaf(V);

            p >>= 1;
            while (p >= 1) {
                seg[p] = combine(seg[2 * p], seg[2 * p + 1]);
                p >>= 1;
            }
        } else {
            int E, D;
            cin >> E >> D;
            --E;

            int l = E + N;
            int r = D + N;

            Node left, right;

            while (l < r) {
                if (l & 1) {
                    left = combine(left, seg[l]);
                    ++l;
                }
                if (r & 1) {
                    --r;
                    right = combine(seg[r], right);
                }
                l >>= 1;
                r >>= 1;
            }

            Node res = combine(left, right);
            cout << res.ans << '\n';
        }
    }

    return 0;
}
